#Requires -Version 7.0
[CmdletBinding(SupportsShouldProcess)]
param()
$ErrorActionPreference='Stop'
$repo='<repo>'
$base=Join-Path $repo 'docs/evidence/release15/frozen-af6ee6f/live-ui/conflict-retirement-supplement'
$manifestPath=Join-Path $base 'manifest.json'
$manifest=Get-Content -LiteralPath $manifestPath -Raw | ConvertFrom-Json -AsHashtable
foreach($p in $manifest.files){if((Get-FileHash -LiteralPath $p.retainedCopy).Hash -cne $p.sha256){throw 'Preserved evidence/source hash mismatch'}}
$retained=Join-Path $base 'retained'
$lane=Join-Path $retained 'docs/evidence/release15/frozen-af6ee6f/live-ui'
$runtimePath=Join-Path $lane 'runtime-receipts/live-scale-4.json'
$runtime=Get-Content -LiteralPath $runtimePath -Raw | ConvertFrom-Json -AsHashtable
$uiPath=Join-Path $lane 'runtime-receipts/live-scale-4-failure-ui.json'
$ui=Get-Content -LiteralPath $uiPath -Raw | ConvertFrom-Json -AsHashtable
[xml]$native=Get-Content -LiteralPath (Join-Path $lane 'live-ui.xml') -Raw
$failed=@($native.SelectNodes('//testcase[failure or error]'))[0]
$effective=Get-Content -LiteralPath $manifest.effectiveSnapshot -Raw | ConvertFrom-Json -AsHashtable
$all=@($effective.functional)+@($effective.technical)+@($effective.testing)
$references=@('FR-REQUESTFEEDBACK-030#UI-FEEDBACK-02','FR-REQUESTFEEDBACK-030#UI-FEEDBACK-04','FR-REQUESTFEEDBACK-030#UI-FEEDBACK-05','TEST-REQUESTFEEDBACK-143#UI-FEEDBACK-02','TEST-REQUESTFEEDBACK-143#UI-FEEDBACK-04','TEST-REQUESTFEEDBACK-143#UI-FEEDBACK-05','TR-CONNECTION-RECOVERY-009#TR-09-C01','TEST-CONNECTIONRECOVERY-109#VERIFY-TR-09','TR-MULTIPLAYER-INTEGRATION-034#TR-34-C01','TR-MULTIPLAYER-INTEGRATION-034#TR-34-C02','TR-ROOM-SYNCRECOVERY-038#LIVE-07','TEST-ROOMSYNC-139#LIVE-07')
$requirementPins=@(foreach($reference in $references){
 $parts=$reference -split '#';$record=@($all | Where-Object id -CEQ $parts[0]);$criterion=@($record[0].acceptanceCriteria | Where-Object id -CEQ $parts[1])
 if($record.Count -ne 1 -or $criterion.Count -ne 1){throw 'Missing current requirement/criterion'}
 [ordered]@{reference=$reference;text=$criterion[0].text;isSatisfiedAtRead=$criterion[0].isSatisfied;recordStatusAtRead=$record[0].status}
})
$uiProjection=@(foreach($s in $ui.uiStates){
 $alias=[regex]::Match($s.body,'(?m)^[^\r\n]*?(Guest (?:Cedar|Oak|Maple|Willow|Pine|Elm|Birch|Aspen) [A-Za-z0-9_-]{6})\s*$').Groups[1].Value
 $ownRow=@($s.body -split "`n" | Where-Object {$_ -match ('^.*'+[regex]::Escape($alias)+'\s*\t')})
 [ordered]@{player=$s.player;closed=$s.closed;browserConnected=$s.browserConnected;liveConnected=$s.body.Contains(([char]0x25CF)+' Live updates connected');fullRoster=$s.body.Contains('4 / 4 players');round3=$s.body.Contains('Round 3 / 8');profileAlias=$alias;hasPendingGameText=$s.body.Contains('Retry pending game request');hasSubmitAnswer=$s.body.Contains('Submit answer');ownRoundRow=@($ownRow | Select-Object -First 1);qualification='Body text is a post-failure snapshot, not DOM busy/disabled attributes or exact failure-probe state.'}
})
$axes=@(
 [ordered]@{axis='crash_restart_replay';assessment='Existing canonical recovery unchanged. This known409 phase waits for frontend retirement; it cannot replay a pending command or silently start a new one. Lost-body/server uncertainty remains distinct from explicit409. No process crash evidence is supplied.'},
 [ordered]@{axis='ordering_concurrency';assessment='Driver observes409 headers/body outcome before frontend finishes its own JSON consumption, refresh and finally. A post409 retirement callback may legitimately sample a present disabled pending control. Fresh unknown-pending rejection is correct before a new logical call but incorrectly reused within the known call. All four snapshots later have no pending text; this does not backfill exact earlier DOM attributes.'},
 [ordered]@{axis='boundary_malformed';assessment='A separate known-retirement waiting path must preserve exact scope/visible/authorized/finite-version validation. Disabled or enabled pending remains waiting, never recovery permission; absent pending but busy remains waiting. Unknown fresh pending still rejects. Malformed/denied/missing/wrong-scope probes fail without silently becoming success.'},
 [ordered]@{axis='supported_host_inert_unsupported';assessment='Actual Chromium lane failure is retained; isolated124 controls were not DOM integration. Strict sibling is a source finding only because the chain stopped before strict ran. No host/transport replacement, platform fallback or input class is invented.'},
 [ordered]@{axis='lifecycle_terminal';assessment='Await complete retirement before discarding held identity and running the fresh action. All started probes/actions must remain observed, errors propagate unchanged, and timeout must fail rather than count. Existing capture work ownership and verified cleanup remain. Known409 whose frontend body never retires must remain bounded failure, not permission to retry a changed payload.'},
 [ordered]@{axis='workspace_session_agent_isolation';assessment='Retirement capability is used only immediately after the same captured exact409 command. Keep page/aggregate/action/profile and full retry-payload identity checks. No unknown old pending may enter this phase through fresh preparation; inspect both matrix and strict callsites.'},
 [ordered]@{axis='legacy_upgrade';assessment='Application, capacity15/observer25, historical match compatibility, deadlines and holdout policy are untouched. Prior124 helper evidence remains historical and no longer suffices to certify the actual DOM retirement boundary. Earlier failed fdee8/1/5 is retained separately.'},
 [ordered]@{axis='user_visible_output';assessment='The assertion aborted a valid UI retirement interval rather than waiting for the sender to become idle. Preserve the guard and prove the actual wait boundary, own-round solve count, all eight rounds/shared ranking and truthful cleanup. No current game completion/HV/deployment follows from this diagnosis.'}
)
$r=[ordered]@{
 recordedAt=(Get-Date).ToString('o');kind='read-only af6ee6f known-conflict-retirement diagnosis; not HV';sourceHead=$manifest.sourceHead;validationRunId=$manifest.validationRunId;ownSessionId=$manifest.ownSessionId;ownRequestId=$manifest.ownRequestId;parentSessionId=$manifest.parentSessionId;parentRequestId=$manifest.parentRequestId
 preservation=@{manifest=$manifestPath;sha256=(Get-FileHash $manifestPath).Hash;files=$manifest.files.Count;allRetainedHashesRechecked=$true;originalsRetained=$true;sourceCopies=$manifest.files | Where-Object source -Like '*.ts*'}
 native=@{cases=@($native.SelectNodes('//testcase')).Count;passed=@($native.SelectNodes('//testcase[not(failure) and not(error) and not(skipped)]')).Count;failed=@($native.SelectNodes('//testcase[failure or error]')).Count;skipped=@($native.SelectNodes('//testcase[skipped]')).Count;failedName=$failed.name;seconds=$failed.time;originalError=$failed.error.InnerText;qualification='Native actual/expected diff text is visually merged in the raw report; source stack and original bytes retained rather than silently normalizing it.'}
 runtime=@{players=$runtime.players;phase=$runtime.phase;completed=$runtime.completed;rounds=$runtime.rounds;uiSolves=$runtime.uiSolves;uncertainUiRetries=$runtime.uncertainUiRetries;cleanupFailures=$runtime.cleanupFailures;bodyFailures=$runtime.commandBodyFailures;requestFailureTotal=$runtime.requestFailureTotal;instrumentationFailures=$runtime.requestDiagnostics.failureTotal;pendingAtDispose=$runtime.requestDiagnostics.pendingAtDispose;round3Acknowledgements=@($runtime.commandAcknowledgements | Where-Object phase -EQ 'UI round 3');readiness=$runtime.readinessObservations}
 uiStates=$uiProjection;visualInspection=@{file='browser-artifacts/live-player-counts.integra-bacd2-rs-complete-eight-UI-rounds/failure-ui.png';observed='Viewed retained full screenshot: player0 Guest Birch, connected4/4 room, round3 Up, own solved5points, scorecard actor2 Guest Elm solving. Screenshot is post-failure and is not the exact transient retirement sample.'}
 confirmedFinding='Known409 retirement and unknown fresh preparation share mode=fresh. commandUiState checks pending absent before busy, so a known in-flight/pending409 can throw before normal retirement. Matrix retired callback86 invokes this mode only after actual409 in shared coordinator78. Strict after409 also invokes fresh at113. Product frontend consumes409 JSON, clears pending, refreshes, then clears busy at game-panel209-240.'
 actorAttribution=@{confirmed='All4 snapshots open/connected/full roster/round3. Actor3 has explicit successful answer acknowledgement. Actor2 is the only unsolved own row and still has Submit answer.';inference='Actor2 is the likely failing logical call from batch2/3 and11successful solve counts, but native stack/409 timing records do not contain the exact failing commandId or explicit player index.';exactFailingRequestActorJoinVerified=$false}
 underlyingCoverageGap='Prior124 SAME oracle tested real classifier and shared coordinator, but its retired callbacks resolved or deferred synthetically without composing the actual classifier/DOM transition used by the live adapters. Correct await ownership of a stub did not prove the adapter selected the correct waiting mode. No prior gate is rewritten as DOM evidence.'
 minimalCorrection='Separate known-conflict retirement waiting from strict fresh preparation. Only post409 callbacks may enter it; wait for pending absent, busy=false and valid version under existing bounds, including disabled/enabled pending transitions with no retry click. Fresh pending continues to fail even when busy. Bind SAME oracle to the real waiting/classifier boundary and both matrix/strict adapters; preserve12/four attempts, game assertions and source policy.'
 requiredControls=@('Known409 disabled pending+busy -> absent pending+busy -> idle absent completes only after retirement.','Known409 enabled pending remains waiting without clicking or authorizing uncertain retry.','Wrong use of fresh mode during known retirement is rejected by the composed oracle.','Prematurely acknowledging pending/busy state is rejected.','Unknown fresh pending with busy=true orfalse still throws before a new action.','Retirement stale version waits; missing/denied/malformed/wrong scope and probe error remain failure, not success.','If retirement never completes, normal assertion bound fails; no new sleep/timeouts/catchall/retry classification.','Strict only changes post409 wait phase; fresh preflight, fail-only successful ack and four conflicts remain.','Full124 earlier controls retained as history; expanded correct/wrong mock gate precedes helper delta and actual full lanes rerun on successor frozen source.')
 requirementPins=$requirementPins;axes=$axes
 unknowns=@('Exact busy value/visibility/button.disabled at failing poll is not retained separately; classifier disabled includes a present invisible or disabled button.','Exact failing409 command UUID/player is not directly joined; actor2 attribution is an inference from own-row/count/batch evidence.','All five reported409answer timings25-42ms lack per-actor/phase/command keys; they cannot individually identify the failing conflict or prove its underlying cause.','Post-failure snapshots with no pending controls do not prove the prior sampled UI was already retired.','No transport/load/server/driver root cause is established. The17.487second case differs from earlier ten-player slow-response observation.','Strict sibling was not executed by the stopped af chain; source similarity is not a second observed runtime failure.','New correction/oracle and actual successor full UI outcomes remain pending at this initial diagnostic read.')
 testsBuildsModelsProvidersRunByThisAgent=$false;sourceOrRequirementsEditsByThisAgent=0;accuracy=99;completeness=97;ratingsQualification='Source/native/preservation facts verified; exact transient attributes, actor/request and transport causes remain unknown.'
}
$jsonPath=Join-Path $base 'diagnosis.json';$mdPath=Join-Path $base 'diagnosis.md';$producerPath=Join-Path $base 'diagnosis-producer.ps1'
if(-not $PSCmdlet.ShouldProcess($base,'Save safe source/native/requirements diagnosis without changing original failed evidence')){return}
foreach($path in @($jsonPath,$mdPath,$producerPath)){if(Test-Path -LiteralPath $path){throw 'Refusing overwrite of diagnosis'}}
$r | ConvertTo-Json -Depth 22 | Set-Content -LiteralPath $jsonPath -Encoding utf8NoBOM
$md=@"
# Known conflict retirement diagnosis

$($r.recordedAt). Read-only source diagnosis, not hostile validation or a passing game claim.

Frozen af6ee6f actual matrix has2passed/1failed/11skipped. The4-player case failed after17.487seconds in round3 with11UI-acknowledged own-round solves, zero uncertain retries, zero driver body failures, zero cleanup failures and zero instrumentation failures. All4 final UI snapshots remain open/live connected with4/4players. Player2 is the only unsolved own row; player3 has a recorded successful command acknowledgement. Player2 is therefore the likely failed logical call, but the exact409 Request actor/command join is not retained and remains an inference.

The confirmed source defect is phase conflation: shared coordinator handles actual409, then matrix retired callback uses mode fresh. That mode rejects any pending control before checking busy. The frontend may still be consuming the known409 body or refreshing before clearing pending/busy. The strict post409 branch uses the same fresh guard and is a source sibling; strict did not run in the failed chain. Later snapshots have no pending text, which does not erase the earlier sampled pending state. No server, driver or transport cause is established.

The safe correction is a known-conflict retirement waiting phase used only after the captured409. It must wait for pending absent and busy=false with valid version, without replaying that pending control. Keep unknown fresh-pending rejection strict before starting a new intent. Do not move the fresh assertion behind busy globally. Preserve scope/denial/malformed checks, original errors, exact request/payload identity, existing12/four attempts, game deadlines, own-round solve assertions and cleanup.

The prior124 SAME oracle was isolated helper evidence: its retirement callback was synthetic and did not compose the actual classifier/DOM adapter transition. Deferred Promise ownership did not prove the adapter chose the correct mode. An expanded SAME correct/wrong oracle must exercise the real waiting boundary, including busy+disabled, busy+absent, idle+enabled, then idle+absent, and reject unknown fresh pending and premature retirement. Earlier124 receipts remain unchanged as history; full browser validation remains required.

All31 original native/context/PNG/runtime/source files were copied and hash-verified; originals retained. The retained screenshot was viewed and agrees with player0/connected full roster/round3/three solved rows, but is not the transient failing probe. Existing current feedback/canonical retry/multiplayer criteria are pinned in diagnosis.json. Eight whole-chain axes and seven precise unknowns are explicit there. No source, tests, requirements, builds, provider or model/HV changes by this agent. Accuracy99%, completeness97%, reflecting unresolved exact transient attributes, actor/request linkage and transport cause.
"@
$md | Set-Content -LiteralPath $mdPath -Encoding utf8NoBOM
Copy-Item -LiteralPath $PSCommandPath -Destination $producerPath
if((Get-FileHash $PSCommandPath).Hash -cne (Get-FileHash $producerPath).Hash){throw 'Diagnosis producer copy mismatch'}
[ordered]@{recordedAt=$r.recordedAt;outputs=@($jsonPath,$mdPath,$producerPath | ForEach-Object {[ordered]@{path=$_;sha256=(Get-FileHash $_).Hash}});unknowns=$r.unknowns.Count;axes=$r.axes.Count} | ConvertTo-Json -Depth 6
